package server

import (
	"reflect"
	"strings"
	"time"

	"github.com/slopster67/mcpproxy-go/internal/config"
)

// Management tool input schemas are generated by reflection from the same Go
// request types the dashboard decodes, so MCP and REST cannot drift.

func jsonFieldName(f reflect.StructField) string {
	tag := f.Tag.Get("json")
	if tag == "-" || !f.IsExported() {
		return ""
	}
	name, _, _ := strings.Cut(tag, ",")
	if name == "" {
		return f.Name
	}
	return name
}

// jsonSchemaForType renders the JSON schema of a Go type the way encoding/json
// sees it: pointers are transparent, a slice is an array, a map with string
// values is an object, a struct is an object of its JSON-tagged fields.
func jsonSchemaForType(t reflect.Type) map[string]any {
	for t.Kind() == reflect.Pointer {
		t = t.Elem()
	}
	if t == reflect.TypeOf(config.OAuthPatch{}) {
		schema := jsonSchemaForType(reflect.TypeOf(config.OAuthConfig{}))
		for name, property := range schema["properties"].(map[string]any) {
			schema["properties"].(map[string]any)[name] = map[string]any{"anyOf": []any{property, map[string]any{"type": "null"}}}
		}
		schema["additionalProperties"] = false
		schema["description"] = "OAuth overrides. Omit a field to preserve it; null resets it to automatic discovery."
		return schema
	}
	if t == reflect.TypeOf(time.Time{}) {
		return map[string]any{"type": "string", "format": "date-time"}
	}
	if t == reflect.TypeOf(config.Duration(0)) {
		return map[string]any{"type": "string", "description": "Duration, for example 30s or 2m."}
	}
	switch t.Kind() {
	case reflect.Bool:
		return map[string]any{"type": "boolean"}
	case reflect.String:
		return map[string]any{"type": "string"}
	case reflect.Int, reflect.Int32, reflect.Int64, reflect.Uint, reflect.Uint32, reflect.Uint64:
		return map[string]any{"type": "integer"}
	case reflect.Float32, reflect.Float64:
		return map[string]any{"type": "number"}
	case reflect.Slice:
		return map[string]any{"type": "array", "items": jsonSchemaForType(t.Elem())}
	case reflect.Map:
		return map[string]any{"type": "object", "additionalProperties": jsonSchemaForType(t.Elem())}
	case reflect.Struct:
		props := map[string]any{}
		for i := 0; i < t.NumField(); i++ {
			if name := jsonFieldName(t.Field(i)); name != "" {
				props[name] = jsonSchemaForType(t.Field(i).Type)
			}
		}
		return map[string]any{"type": "object", "properties": props}
	}
	return map[string]any{}
}
